19	  GEN_AI_CONVERSATION_ID,
20	  GEN_AI_INPUT_MESSAGES,
21	  GEN_AI_OPERATION_NAME,
22	  GEN_AI_OUTPUT_MESSAGES,
23	  SERVICE_DESCRIPTION,
24	  SERVICE_NAME,
25	} from './constants.js';
26	import { sessionId } from '../utils/session.js';
