7	/**
8	 * Safely stringifies an object to JSON, handling circular references by replacing them with [Circular].
9	 *
10	 * @param obj - The object to stringify
11	 * @param space - Optional space parameter for formatting (defaults to no formatting)
12	 * @returns JSON string with circular references replaced by [Circular]
13	 */
14	import type { Config } from '../config/config.js';
15	
16	export function safeJsonStringify(
17	  obj: unknown,
18	  space?: string | number,
19	): string {
20	  const seen = new WeakSet();
21	  return JSON.stringify(
22	    obj,
23	    (key, value) => {
24	      if (typeof value === 'object' && value !== null) {
25	        if (seen.has(value)) {
26	          return '[Circular]';
27	        }
28	        seen.add(value);
29	      }
30	      // eslint-disable-next-line @typescript-eslint/no-unsafe-return
31	      return value;
32	    },
33	    space,
34	  );
35	}
