37	// eslint-disable-next-line @typescript-eslint/no-explicit-any
38	function removeEmptyObjects(data: any): object {
39	  const cleanedObject: { [key: string]: unknown } = {};
40	  for (const k in data) {
41	    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
42	    const v = data[k];
43	    if (v !== null && v !== undefined && typeof v === 'boolean') {
44	      cleanedObject[k] = v;
45	    }
46	  }
47	
48	  return cleanedObject;
49	}
