51	/**
52	 * Safely stringifies an object to JSON, retaining only non-null, Boolean-valued members.
53	 *
54	 * @param obj - The object to stringify
55	 * @returns JSON string with circular references skipped and only non-null, Boolean member values retained.
56	 */
57	// eslint-disable-next-line @typescript-eslint/no-explicit-any
58	export function safeJsonStringifyBooleanValuesOnly(obj: any): string {
59	  let configSeen = false;
60	  return JSON.stringify(removeEmptyObjects(obj), (key, value) => {
61	    // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
62	    if ((value as Config) !== null && !configSeen) {
63	      configSeen = true;
64	      // eslint-disable-next-line @typescript-eslint/no-unsafe-return
65	      return value;
66	    }
67	    if (typeof value === 'boolean') {
68	      return value;
69	    }
70	    return '';
71	  });
72	}
