47	/**
48	 * Safely prepares a value for inclusion as a telemetry span attribute.
49	 *
50	 * - Strings are returned unchanged when their length is within `maxLength`,
51	 *   and otherwise truncated at grapheme-cluster boundaries (so multi-byte
52	 *   unicode characters are never split) with a
53	 *   `...[TRUNCATED: original length N]` suffix.
54	 * - Objects are `JSON.stringify`-ed (via {@link safeJsonStringify}) and then
55	 *   truncated with the same logic.
56	 * - Numbers and booleans are returned unchanged.
57	 * - `undefined`, functions and symbols return `undefined`.
58	 *
59	 * @param value The value to prepare.
60	 * @param maxLength The maximum length of the resulting string attribute.
61	 * @returns An {@link AttributeValue} safe for telemetry, or `undefined`.
62	 */
63	export function truncateForTelemetry(
64	  value: unknown,
65	  maxLength = 10000,
66	): AttributeValue | undefined {
67	  if (typeof value === 'string') {
68	    return truncateString(
69	      value,
70	      maxLength,
71	      `...[TRUNCATED: original length ${value.length}]`,
72	    );
73	  }
74	
75	  if (typeof value === 'number' || typeof value === 'boolean') {
76	    return value;
77	  }
78	
79	  if (typeof value === 'object' && value !== null) {
80	    const stringified = safeJsonStringify(value);
81	    return truncateString(
82	      stringified,
83	      maxLength,
84	      `...[TRUNCATED: original length ${stringified.length}]`,
85	    );
86	  }
87	
88	  // undefined, functions, symbols and null are not representable.
89	  return undefined;
90	}
