103	/**
104	 * Runs a function in a new OpenTelemetry span.
105	 *
106	 * The `meta` object will be automatically used to set the span's status and attributes upon completion.
107	 *
108	 * If the callback returns an async iterable (i.e. a streaming operation), the
109	 * span is kept open and the iterable is wrapped so that the span is only ended
110	 * once iteration completes (or throws). This ensures spans close automatically
111	 * when streams finish, without the caller having to manage the span lifecycle.
112	 *
113	 * @example
114	 * ```typescript
115	 * runInDevTraceSpan({ operation: GeminiCliOperation.LLMCall }, ({ metadata }) => {
116	 *   metadata.input = { foo: 'bar' };
117	 *   // ... do work ...
118	 *   metadata.output = { result: 'baz' };
119	 *   metadata.attributes['my.custom.attribute'] = 'some-value';
120	 * });
121	 * ```
122	 *
123	 * @param opts The options for the span. `logPrompts` controls whether prompt
124	 *   content (`metadata.input`/`metadata.output`) is included on the span.
125	 * @param fn The function to run in the span.
126	 * @returns The result of the function.
127	 */
128	export async function runInDevTraceSpan<R>(
129	  opts: SpanOptions & { operation: GeminiCliOperation; logPrompts?: boolean },
130	  fn: ({ metadata }: { metadata: SpanMetadata }) => Promise<R>,
131	): Promise<R> {
132	  const { operation, logPrompts, ...restOfSpanOpts } = opts;
133	
134	  const tracer = trace.getTracer(TRACER_NAME, TRACER_VERSION);
135	  return tracer.startActiveSpan(operation, restOfSpanOpts, async (span) => {
136	    const meta: SpanMetadata = {
137	      name: operation,
138	      attributes: {
139	        [GEN_AI_OPERATION_NAME]: operation,
140	        [GEN_AI_AGENT_NAME]: SERVICE_NAME,
141	        [GEN_AI_AGENT_DESCRIPTION]: SERVICE_DESCRIPTION,
142	        [GEN_AI_CONVERSATION_ID]: sessionId,
143	      },
144	    };
145	    let spanEnded = false;
146	    const endSpan = () => {
147	      // Guard against being invoked more than once (e.g. an error surfaced
148	      // during stream iteration after the span was otherwise complete).
149	      if (spanEnded) {
150	        return;
151	      }
152	      spanEnded = true;
153	      try {
154	        if (logPrompts !== false) {
155	          if (meta.input !== undefined) {
156	            const input = truncateForTelemetry(meta.input);
157	            if (input !== undefined) {
158	              span.setAttribute(GEN_AI_INPUT_MESSAGES, input);
159	            }
160	          }
161	          if (meta.output !== undefined) {
162	            const output = truncateForTelemetry(meta.output);
163	            if (output !== undefined) {
164	              span.setAttribute(GEN_AI_OUTPUT_MESSAGES, output);
165	            }
166	          }
167	        }
168	        for (const [key, value] of Object.entries(meta.attributes)) {
169	          span.setAttribute(key, value);
170	        }
171	        if (meta.error) {
172	          span.setStatus({
173	            code: SpanStatusCode.ERROR,
174	            message: getErrorMessage(meta.error),
175	          });
176	          if (meta.error instanceof Error) {
177	            span.recordException(meta.error);
178	          }
179	        } else {
180	          span.setStatus({ code: SpanStatusCode.OK });
181	        }
182	      } catch (e) {
183	        // Log the error but don't rethrow, to ensure span.end() is called.
184	        diag.error('Error setting span attributes in endSpan', e);
185	        span.setStatus({
186	          code: SpanStatusCode.ERROR,
187	          message: `Error in endSpan: ${getErrorMessage(e)}`,
188	        });
189	      } finally {
190	        span.end();
191	      }
192	    };
193	
194	    try {
195	      const result = await fn({ metadata: meta });
196	
197	      if (isAsyncIterable(result)) {
198	        // Streaming operation: keep the span open and only end it once the
199	        // stream has been fully consumed (or has thrown).
200	        const source = result as AsyncIterable<unknown>;
201	        async function* wrapWithSpan(): AsyncGenerator<unknown> {
202	          try {
203	            yield* source;
204	          } catch (e) {
205	            meta.error = e;
206	            // End the span before re-throwing so the error is recorded.
207	            endSpan();
208	            throw e;
209	          }
210	          endSpan();
211	        }
212	        return wrapWithSpan() as unknown as R;
213	      }
214	
215	      // Non-streaming operation: close the span immediately.
216	      endSpan();
217	      return result;
218	    } catch (e) {
219	      meta.error = e;
220	      endSpan();
221	      throw e;
222	    }
223	  });
224	}
